__NUXT_JSONP__("/ru/feature", (function(a){return {data:[{details:{slug:"ru",pageTitle:"5 причин Почему Люди Выбирают MLI | Mentor Language Institute",pageDescription:"С момента нашего открытия мы помогли более 17 000 ученикам улучшить свои знания английского языка.",section1:{title:"5 причин Почему Люди Выбирают MLI",image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fmli-mentor.jpg"},section2:{title:"5 Характерных черт Mentor Language Institute",description:["С момента нашего открытия мы помогли более 17 000 ученикам улучшить свои знания английского языка. Почему студенты выбирают MLI, хотя в Лос-Анджелесе так много языковых школ? Мы провели опрос среди студентов MLI, и их ответы приведены ниже."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fsurvey.jpg",notes:"Период опроса: С января по июнь 2017 года \u002F участвовали 342 студента"},section3:[{title:"No.1 : Разумная цена",subtitle:"Отличная цена! От $209 в неделю. Дневные занятия на 40% дешевле утренних!",description:["Первая причина выбрать MLI - это доступная цена.","Чем дольше вы посещаете нашу школу, тем дешевле плата за обучение. Если вы подаете заявку на 1 месяц, плата за обучение составляет $1,220 а это  \u003Cb\u003E$305 в неделю\u003C\u002Fb\u003E. (уже эта цена отличная!), но если вы подаете заявку на 1 год (48 недель), плата за обучение составляет $10,032 а это  \u003Cspan style=\"color: #ff0000; font-weight: bold;\"\u003E$209 в неделю\u003C\u002Fspan\u003E. Пожалуйста, сравните наши тарифы с другими школами."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002FPRICE_CHART_WEB_JAN06.jpg",links:[{icon:a,text:"больше информации о ценах на обучение",link:"\u002Fru\u002Fprice"}]},{title:"No.2 : Отличное месторасположение",subtitle:"Вествуд и Голливуд: популярные районы Лос-Анджелеса",description:["«Мы находимся в замечательных, популярных районах Лос-Анджелеса, Вествуд и Голливуд. Студенты могут легко добраться до известных мест, таких как Санта-Моника, центр Лос-Анджелеса и т.д."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgreat-location.jpg",locations:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fwestwood-campus.jpg",label:"Вествед Кампус"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fhollywood-campus.jpg",label:"Голливуд Кампус"}],links:[{icon:a,text:"Дополнительная информация о кампусе в Вествуде",link:"\u002Fru\u002Fwestwood"},{icon:a,text:"Дополнительная информация о кампусе в Голливуде",link:"\u002Fru\u002Fhollywood"}]},{title:"No.3: Разнообразие курсов по подготовке в колледж",subtitle:"Многие студенты переводятся в колледжи Лос-Анджелеса и Санта-Моники после обучения в MLI",description:["Мы предлагаем популярные курсы по подготовке к экзамену для поступления в колледж, такие как TOEFL®, IELTS ™. Многие студенты переводятся в университет Калифорнии в Лос Анджелесе и колледж Санта-Моники после обучения в MLI"],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgoing-to-college.jpg",links:[{icon:a,text:"Дополнительная информация о колледжах",link:"\u002Fru\u002Fgoing-to-college"}]},{title:"No.4 : Гибкое расписание занятий",subtitle:"Мы предлагаем утренние, дневные и вечерние занятия.",description:["MLI предлагает 3 разных расписания. Студенты могут выбрать утренние, дневные и вечерние занятия."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fclass-schedule.png",notes:"Это график занятий в Вествуд кампусе. Если вы хотите расписание занятий в Голливуде, пожалуйста, свяжитесь с нами»."},{title:"No.5 : Общежитие",subtitle:"Мы предлагаем возможность общаться со студентами со всего мира в нашем общежитии.",description:["Мы организуем не только проживание в семье, но и общежития. У нас более 40 комнат в районе Лос-Анджелеса и общежития расположены рядом с каждым кампусом. Многие студенты предпочитают проживание в общежитии, если они впервые в США."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fdormitory.jpg",links:[{icon:a,text:"Дополнительная информация о жилье",link:"\u002Fru\u002Fstay"}]}],dir:"\u002Ffeature",path:"\u002Ffeature\u002Fru",extension:".json",createdAt:"2026-10-22T16:31:29.207Z",updatedAt:"2026-03-24T13:34:16.441Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));